{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATOR_CHARS = new Set(['+', '#', '.', '/', ';', '?', '&']);
const RESERVED_OPERATOR_CHARS = new Set(['=', ',', '!', '@', '|']);

const NAME_RE = /^(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+(?:\.(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+)*$/;
const MODIFIER_RE = /^[1-9][0-9]{0,3}$/;

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');

  const parts = [];
  let literal = '';
  let i = 0;

  while (i < template.length) {
    const ch = template[i];
    if (ch === '{') {
      if (literal) {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }
      const close = template.indexOf('}', i + 1);
      if (close === -1) {
        throw new UriTemplateError(`unterminated expression at ${i}`, i);
      }
      const inner = template.slice(i + 1, close);
      parts.push(parseExpression(inner, i));
      i = close + 1;
    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literal += ch;
      i += 1;
    }
  }

  if (literal) parts.push({ type: 'literal', value: literal });
  return parts;
}

function parseExpression(inner, braceIdx) {
  if (inner === '') throw new UriTemplateError(`empty expression at ${braceIdx}`, braceIdx);

  let operator = '';
  let rest = inner;
  const first = inner[0];

  if (RESERVED_OPERATOR_CHARS.has(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${braceIdx}`, braceIdx);
  }
  if (OPERATOR_CHARS.has(first)) {
    operator = first;
    rest = inner.slice(1);
  }

  const specs = rest.split(',');
  const variables = specs.map((spec) => parseVarSpec(spec, braceIdx));
  return { type: 'expression', operator, variables };
}

function parseVarSpec(spec, braceIdx) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${braceIdx}`, braceIdx);

  let explode = false;
  let maxLength = null;
  let namePart;

  if (spec.endsWith('*')) {
    explode = true;
    namePart = spec.slice(0, -1);
  } else {
    const idx = spec.indexOf(':');
    if (idx !== -1) {
      namePart = spec.slice(0, idx);
      const modStr = spec.slice(idx + 1);
      if (!MODIFIER_RE.test(modStr)) {
        throw new UriTemplateError(`invalid prefix modifier ':${modStr}' at ${braceIdx}`, braceIdx);
      }
      maxLength = Number(modStr);
    } else {
      namePart = spec;
    }
  }

  if (!NAME_RE.test(namePart)) {
    throw new UriTemplateError(`invalid variable name '${namePart}' at ${braceIdx}`, braceIdx);
  }

  return { name: namePart, explode, maxLength };
}
"}

