import { PointerError, formatPointer, parsePointer, resolve, navigateTokens, stepInto, kindOf } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const ARRAY_INDEX = /^(0|[1-9][0-9]*)$/;

function definePropertySafe(obj, key, value) {
  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
  return obj;
}

/**
 * Deep-copy a value, verifying it is JSON-compatible data along the way.
 *
 * @param {unknown} value value to copy
 * @param {string} kind noun used in the error message ('document' or 'value')
 * @returns {unknown} an independent deep copy
 */
function deepClone(value, kind) {
  if (value === null) return null;
  const t = typeof value;
  if (t === 'boolean' || t === 'string') return value;
  if (t === 'number') {
    if (!Number.isFinite(value)) throw new Error(`${kind} is not JSON data`);
    return value;
  }
  if (Array.isArray(value)) return value.map((item) => deepClone(item, kind));
  if (t === 'object') {
    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) throw new Error(`${kind} is not JSON data`);
    const result = {};
    for (const key of Object.keys(value)) {
      definePropertySafe(result, key, deepClone(value[key], kind));
    }
    return result;
  }
  throw new Error(`${kind} is not JSON data`);
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((v, i) => deepEqual(v, b[i]));
  }
  if (a !== null && b !== null && typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
    const ak = Object.keys(a);
    const bk = Object.keys(b);
    if (ak.length !== bk.length) return false;
    return ak.every((key) => Object.prototype.hasOwnProperty.call(b, key) && deepEqual(a[key], b[key]));
  }
  return false;
}

function pointerEqual(a, b) {
  return a.length === b.length && a.every((token, i) => token === b[i]);
}

function isProperPrefix(a, b) {
  return a.length < b.length && a.every((token, i) => token === b[i]);
}

/** Remove the value named by a pointer, returning it alongside the mutated document. */
function removeAt(document, pointer) {
  const tokens = parsePointer(pointer);
  if (tokens.length === 0) throw new Error('cannot remove the whole document');
  const parentTokens = tokens.slice(0, -1);
  const key = tokens[tokens.length - 1];
  const parent = navigateTokens(document, parentTokens);
  const fullPointer = formatPointer(tokens);
  const value = stepInto(parent, key, fullPointer);
  if (Array.isArray(parent)) {
    parent.splice(Number(key), 1);
  } else {
    delete parent[key];
  }
  return { document, value };
}

/** Insert a value at a pointer, creating or overwriting a member / inserting into an array. */
function addAt(document, pointer, value) {
  const tokens = parsePointer(pointer);
  if (tokens.length === 0) return value;
  const parentTokens = tokens.slice(0, -1);
  const key = tokens[tokens.length - 1];
  const parent = navigateTokens(document, parentTokens);
  const fullPointer = formatPointer(tokens);
  if (Array.isArray(parent)) {
    let index;
    if (key === '-') {
      index = parent.length;
    } else {
      if (!ARRAY_INDEX.test(key)) throw new PointerError(`invalid array index: ${key} at ${fullPointer}`, fullPointer);
      index = Number(key);
      if (index > parent.length) throw new PointerError(`index out of range: ${key} at ${fullPointer}`, fullPointer);
    }
    parent.splice(index, 0, value);
  } else if (parent !== null && typeof parent === 'object') {
    definePropertySafe(parent, key, value);
  } else {
    throw new PointerError(`cannot index into ${kindOf(parent)} at ${fullPointer}`, fullPointer);
  }
  return document;
}

/** Replace the existing value named by a pointer. */
function replaceAt(document, pointer, value) {
  if (pointer === '') return value;
  const tokens = parsePointer(pointer);
  const parentTokens = tokens.slice(0, -1);
  const key = tokens[tokens.length - 1];
  const parent = navigateTokens(document, parentTokens);
  const fullPointer = formatPointer(tokens);
  stepInto(parent, key, fullPointer);
  if (Array.isArray(parent)) {
    parent[Number(key)] = value;
  } else {
    definePropertySafe(parent, key, value);
  }
  return document;
}

function applyOperation(document, operation) {
  if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) {
    throw new Error('operation must be an object');
  }
  const { op: name, path, from } = operation;
  const valid = ['add', 'remove', 'replace', 'move', 'copy', 'test'];
  if (!valid.includes(name)) throw new Error(`unknown operation: ${name}`);
  if (path === undefined) throw new Error(`${name} requires a path`);
  if (['add', 'replace', 'test'].includes(name) && !Object.prototype.hasOwnProperty.call(operation, 'value')) {
    throw new Error(`${name} requires a value`);
  }
  if (['move', 'copy'].includes(name) && from === undefined) {
    throw new Error(`${name} requires a from`);
  }

  switch (name) {
    case 'add': {
      const value = deepClone(operation.value, 'value');
      return addAt(document, path, value);
    }
    case 'remove': {
      if (path === '') throw new Error('cannot remove the whole document');
      return removeAt(document, path).document;
    }
    case 'replace': {
      const value = deepClone(operation.value, 'value');
      return replaceAt(document, path, value);
    }
    case 'move': {
      const fromTokens = parsePointer(from);
      const pathTokens = parsePointer(path);
      if (pointerEqual(fromTokens, pathTokens)) {
        resolve(document, from);
        return document;
      }
      if (isProperPrefix(fromTokens, pathTokens)) {
        throw new Error('cannot move a value into its own child');
      }
      const { document: afterRemove, value } = removeAt(document, from);
      return addAt(afterRemove, path, value);
    }
    case 'copy': {
      const value = deepClone(resolve(document, from), 'value');
      return addAt(document, path, value);
    }
    case 'test': {
      const actual = resolve(document, path);
      if (!deepEqual(actual, operation.value)) throw new Error(`test failed at ${path}`);
      return document;
    }
    default:
      throw new Error(`unknown operation: ${name}`);
  }
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!Array.isArray(operations)) throw new Error('patch must be an array');
  let current = deepClone(document, 'document');
  for (let index = 0; index < operations.length; index += 1) {
    try {
      current = applyOperation(current, operations[index]);
    } catch (error) {
      if (error instanceof PatchError) throw error;
      const cause = error instanceof PointerError ? error : undefined;
      throw new PatchError(error.message, index, cause ? { cause } : undefined);
    }
  }
  return current;
}
