 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  const length = input.length;
  let pos = 0;

  function peek() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function next() {
    const token = peek();
    pos += 1;
    return token;
  }

  function expectEndOrError(token, kind) {
    if (token === null) throw new ExprError(`unexpected end of input at ${length}`, length);
    throw new ExprError(`unexpected token '${tokenText(token)}' at ${token.index}`, token.index);
  }

  function parsePrimary() {
    const token = peek();
    if (token === null) throw new ExprError(`unexpected end of input at ${length}`, length);

    if (token.type === 'number') {
      next();
      return { type: 'number', value: token.value, index: token.index };
    }

    if (token.type === 'name') {
      next();
      const after = peek();
      if (after !== null && after.type === 'lparen') {
        next(); // consume '('
        const args = parseArgs();
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    if (token.type === 'lparen') {
      next();
      const inner = parseAddSub();
      const closing = peek();
      if (closing === null) throw new ExprError(`missing closing parenthesis at ${length}`, length);
      if (closing.type !== 'rparen') throw new ExprError(`missing closing parenthesis at ${closing.index}`, closing.index);
      next();
      return inner;
    }

    throw new ExprError(`unexpected token '${tokenText(token)}' at ${token.index}`, token.index);
  }

  function parseArgs() {
    const args = [];
    const first = peek();
    if (first !== null && first.type === 'rparen') {
      next();
      return args;
    }
    while (true) {
      const arg = parseAddSub();
      args.push(arg);
      const token = peek();
      if (token === null) throw new ExprError(`missing closing parenthesis at ${length}`, length);
      if (token.type === 'comma') {
        next();
        continue;
      }
      if (token.type === 'rparen') {
        next();
        return args;
      }
      throw new ExprError(`unexpected token '${tokenText(token)}' at ${token.index}`, token.index);
    }
