    const token = peek();
    if (token !== null && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      next();
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parsePower();
  }

