    let sum = 0;
    const storedLines = [];
    for (const line of lines) {
      const account = line && line.account;
      const amountCents = line && line.amountCents;
      if (typeof account !== 'string' || !this.#accounts.has(account)) {
        throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${account}`);
      }
      if (!Number.isSafeInteger(amountCents)) throw new LedgerError('NOT_INTEGER', 'amountCents must be a safe integer');
      if (amountCents === 0) throw new LedgerError('ZERO_LINE', 'amountCents must not be zero');
      sum += amountCents;
      storedLines.push(Object.freeze({ account, amountCents }));
    }
    if (sum !== 0) throw new LedgerError('UNBALANCED', 'entry lines must sum to zero');

    this.#seq += 1;
    const stored = Object.freeze({
      id,
      at,
      seq: this.#seq,
      memo,
      lines: Object.freeze(storedLines),
      reverses,
      reversedBy: null,
    });
    this.#entries.set(id, stored);
    this.#order.push(id);
    return stored;
  }

  /**
   * Look up an entry.
   *
   * @param {string} id Entry id.
   * @returns {Readonly<object>|undefined} The entry, if it exists.
   */
  getEntry(id) {
    return this.#entries.get(id);
  }

  /**
   * Entries up to a moment, oldest first.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {Array<Readonly<object>>} Matching entries ordered by time then posting order.
   */
  entries({ asOf = Infinity } = {}) {
    if (asOf !== Infinity && (!Number.isInteger(asOf) || asOf < 0)) {
      throw new LedgerError('BAD_TIME', 'asOf must be a non-negative integer');
    }
    return this.#order
      .map((id) => this.#entries.get(id))
      .filter((entry) => entry.at <= asOf)
      .sort((a, b) => a.at - b.at || a.seq - b.seq);
  }

  /**
   * Debit-positive balance of one account.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Signed balance in cents.
   */
  balance(accountId, options = {}) {
    if (!this.#accounts.has(accountId)) throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    const matching = this.entries(options);
    let total = 0;
    for (const entry of matching) {
      for (const line of entry.lines) {
        if (line.account === accountId) total += line.amountCents;
      }
    }
    return total;
  }

  /**
   * Balance of one account in its own normal direction.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Balance in cents, positive when on the normal side.
   */
  normalBalance(accountId, options = {}) {
    const balance = this.balance(accountId, options);
    const account = this.#accounts.get(accountId);
    return toNormal(account.type, balance);
  }

  /**
   * Debit and credit totals across every account.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {{debits: number, credits: number, byAccount: Record<string, number>}} Trial balance.
   */
  trialBalance(options = {}) {
    let debits = 0;
    let credits = 0;
    const byAccount = {};
    for (const account of this.accounts()) {
      const balance = this.balance(account.id, options);
      byAccount[account.id] = balance;
      if (balance > 0) debits += balance;
      else if (balance < 0) credits += -balance;
    }
    return { debits, credits, byAccount };
  }

  /**
   * Post the mirror image of an entry.
   *
   * @param {string} entryId Entry to reverse.
   * @param {{id: string, at: number, memo?: string}} options Identity and time of the reversal.
   * @returns {Readonly<object>} The reversing entry.
   */
  reverse(entryId, options) {
    const original = this.#entries.get(entryId);
    if (!original) throw new LedgerError('NOT_FOUND', `unknown entry: ${entryId}`);
    if (original.reverses !== null) throw new LedgerError('REVERSAL_OF_REVERSAL', 'cannot reverse a reversal');
    if (original.reversedBy !== null) throw new LedgerError('ALREADY_REVERSED', `entry already reversed: ${entryId}`);
    const { id, at, memo = `reversal of ${entryId}` } = options || {};
    if (Number.isInteger(at) && at < original.at) {
      throw new LedgerError('BAD_TIME', 'reversal cannot precede its entry');
    }
    const lines = original.lines.map((line) => ({ account: line.account, amountCents: -line.amountCents }));
    const reversal = this.post({ id, at, memo, lines }, { reverses: entryId });
    const updatedOriginal = Object.freeze({ ...original, reversedBy: reversal.id });
    this.#entries.set(entryId, updatedOriginal);
    return reversal;
  }

  /**
   * Every line touching one account inside a window, with a running balance.
   *
   * @param {string} accountId Account to report on.
   * @param {{from?: number, to?: number}} [options] Inclusive window.
   * @returns {Array<{entryId: string, at: number, seq: number, amountCents: number, balanceCents: number}>} Statement rows.
   */
  statement(accountId, { from = -Infinity, to = Infinity } = {}) {
    if (!this.#accounts.has(accountId)) throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    const all = this.entries();
    let running = 0;
    const rows = [];
    for (const entry of all) {
      for (const line of entry.lines) {
        if (line.account !== accountId) continue;
        running += line.amountCents;
        if (entry.at >= from && entry.at <= to) {
          rows.push({
            entryId: entry.id,
            at: entry.at,
            seq: entry.seq,
            amountCents: line.amountCents,
            balanceCents: running,
          });
        }
      }
    }
    return rows;
  }
}"}

