import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /[A-Za-z0-9\-._~]/;
const RESERVED = new Set([
  ':', '/', '?', '#', '[', ']', '@', '!', '$', '&', "'", '(', ')', '*', '+', ',', ';', '=',
]);

const OPERATOR_CONFIG = {
  '': { prefix: '', sep: ',', named: false, ifemp: '', reserved: false },
  '+': { prefix: '', sep: ',', named: false, ifemp: '', reserved: true },
  '#': { prefix: '#', sep: ',', named: false, ifemp: '', reserved: true },
  '.': { prefix: '.', sep: '.', named: false, ifemp: '', reserved: false },
  '/': { prefix: '/', sep: '/', named: false, ifemp: '', reserved: false },
  ';': { prefix: ';', sep: ';', named: true, ifemp: '', reserved: false },
  '?': { prefix: '?', sep: '&', named: true, ifemp: '=', reserved: false },
  '&': { prefix: '&', sep: '&', named: true, ifemp: '=', reserved: false },
};

function encodeChar(chStr) {
  const bytes = Buffer.from(chStr, 'utf8');
  let out = '';
  for (const b of bytes) out += `%${b.toString(16).toUpperCase().padStart(2, '0')}`;
  return out;
}

function encodeValue(str, reserved) {
  let out = '';
  let i = 0;
  while (i < str.length) {
    const c = str[i];
    if (reserved && c === '%' && /^[0-9A-Fa-f]{2}$/.test(str.substr(i + 1, 2))) {
      out += str.substr(i, 3);
      i += 3;
      continue;
    }
    if (UNRESERVED_RE.test(c) || (reserved && RESERVED.has(c))) {
      out += c;
      i += 1;
      continue;
    }
    const cp = str.codePointAt(i);
    const chStr = String.fromCodePoint(cp);
    out += encodeChar(chStr);
    i += chStr.length;
  }
  return out;
}

/** Encode literal text: unreserved, reserved and existing percent-triplets pass through. */
function encodeLiteral(str) {
  return encodeValue(str, true);
}

function stringify(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

function scalarPiece(name, value, spec, config) {
  let str = stringify(value, name);
  str = truncate(str, spec.maxLength);
  const encoded = encodeValue(str, config.reserved);
  if (config.named) {
    return encoded === '' ? `${name}${config.ifemp}` : `${name}=${encoded}`;
  }
  return encoded;
}

function usableArrayItems(value) {
  return value.filter((item) => item !== null && item !== undefined);
}

function usableObjectEntries(value) {
  return Object.entries(value).filter(([, v]) => v !== null && v !== undefined);
}

function variablePieces(spec, value, config) {
  const { name, explode, maxLength } = spec;

  if (Array.isArray(value)) {
    const items = usableArrayItems(value);
    if (items.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    if (explode) {
      return items.map((item) => {
        const str = stringify(item, name);
        const encoded = encodeValue(str, config.reserved);
        if (config.named) {
          return encoded === '' ? `${name}${config.ifemp}` : `${name}=${encoded}`;
        }
        return encoded;
      });
    }
    const joined = items.map((item) => encodeValue(stringify(item, name), config.reserved)).join(',');
    if (config.named) {
      return [joined === '' ? `${name}${config.ifemp}` : `${name}=${joined}`];
    }
    return [joined];
  }

  if (typeof value === 'object' && value !== null) {
    const entries = usableObjectEntries(value);
    if (entries.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    if (explode) {
      return entries.map(([key, val]) => {
        const encodedKey = encodeValue(key, config.reserved);
        const encodedVal = encodeValue(stringify(val, name), config.reserved);
        if (config.named && encodedVal === '') {
          return `${encodedKey}${config.ifemp}`;
        }
        return `${encodedKey}=${encodedVal}`;
      });
    }
    const joined = entries
      .flatMap(([key, val]) => [encodeValue(key, config.reserved), encodeValue(stringify(val, name), config.reserved)])
      .join(',');
    if (config.named) {
      return [joined === '' ? `${name}${config.ifemp}` : `${name}=${joined}`];
    }
    return [joined];
  }

  if (value === null || value === undefined) return [];

  return [scalarPiece(name, value, spec, config)];
}

function expandExpression(expression, variables) {
  const config = OPERATOR_CONFIG[expression.operator];
  const pieces = [];

  for (const spec of expression.variables) {
    if (!Object.prototype.hasOwnProperty.call(variables, spec.name)) continue;
    const value = variables[spec.name];
    if (value === null || value === undefined) continue;
    pieces.push(...variablePieces(spec, value, config));
  }

  if (pieces.length === 0) return '';

  return config.prefix + pieces.join(config.sep);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (typeof variables !== 'object' || variables === null) {
    throw new UriTemplateError('variables must be an object');
  }

  const parts = parse(template);
  let result = '';

  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeLiteral(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }

  return result;
}
"}

