{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * Each node represents one distinct prefix, keyed by Unicode code point so
 * characters outside the basic multilingual plane are single steps rather
 * than surrogate pairs. Each node keeps a count of stored words in its
 * subtree so prefix counts are O(prefix length) rather than a subtree walk.
 */
class TrieNode {
  constructor() {
    /** @type {Map<number, TrieNode>} */
    this.children = new Map();
    /** @type {boolean} */
    this.isWord = false;
    /** @type {unknown} */
    this.value = undefined;
    /** @type {number} Number of stored words in this subtree, this node included. */
    this.count = 0;
  }
}

/**
 * Splits a string into an array of code points.
 * @param {string} s String to split.
 * @returns {number[]} Code points in order.
 */
function codePoints(s) {
  const out = [];
  for (const ch of s) out.push(ch.codePointAt(0));
  return out;
}

export class Trie {
  #root = new TrieNode();
  #size = 0;
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const cps = codePoints(word);
    let node = this.#root;
    for (const cp of cps) {
      let child = node.children.get(cp);
      if (!child) {
        child = new TrieNode();
        node.children.set(cp, child);
        this.#nodeCount += 1;
      }
      node = child;
    }
    let previous;
    if (node.isWord) {
      previous = node.value;
      node.value = value;
    } else {
      previous = undefined;
      node.isWord = true;
      node.value = value;
      this.#size += 1;
      // increment count along the path
      let cur = this.#root;
      cur.count += 1;
      for (const cp of cps) {
        cur = cur.children.get(cp);
        cur.count += 1;
      }
    }
    return previous;
  }

  /**
   * Walks to the node for a word, if it exists.
   * @param {string} word Word to walk to.
   * @returns {TrieNode | undefined} Node for that word, or undefined.
   */
  #walk(word) {
    const cps = codePoints(word);
    let node = this.#root;
    for (const cp of cps) {
      node = node.children.get(cp);
      if (!node) return undefined;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#walk(word);
    return node && node.isWord ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#walk(word);
    return !!(node && node.isWord);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const cps = codePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const cp of cps) {
      node = node.children.get(cp);
      if (!node) return false;
      path.push(node);
    }
    if (!node.isWord) return false;
    node.isWord = false;
    node.value = undefined;
    this.#size -= 1;
    for (const n of path) n.count -= 1;
    // prune nodes with no children and not a word, from leaf up
    for (let i = path.length - 1; i > 0; i -= 1) {
      const cur = path[i];
      if (cur.children.size === 0 && !cur.isWord) {
        const parent = path[i - 1];
        const cp = cps[i - 1];
        parent.children.delete(cp);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Validates a limit argument.
   * @param {number} limit Limit to validate.
   * @returns {number} The validated limit.
   */
  #validateLimit(limit) {
    if (
      limit !== Number.POSITIVE_INFINITY &&
      (!Number.isInteger(limit) || limit < 0 || !Number.isSafeInteger(limit))
    ) {
      throw new TypeError('limit must be a non-negative integer');
    }
    return limit;
  }

  /**
   * Collects words in code point order under a node, up to a limit.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix String accumulated so far.
   * @param {number} limit Maximum number of results.
   * @param {Array<[string, unknown]>} out Accumulator.
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.isWord) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort((a, b) => a - b);
    for (const cp of keys) {
      this.#collect(node.children.get(cp), prefix + String.fromCodePoint(cp), limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    this.#validateLimit(limit);
    const node = this.#walk(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    if (typeof text !== 'string') throw new TypeError('text must be a string');
    const cps = codePoints(text);
    let node = this.#root;
    let best = null;
    let acc = '';
    if (node.isWord) best = { word: '', value: node.value };
    for (const cp of cps) {
      const child = node.children.get(cp);
      if (!child) break;
      node = child;
      acc += String.fromCodePoint(cp);
      if (node.isWord) best = { word: acc, value: node.value };
    }
    return best;
  }
}
"}

