import { ARRAY_INDEX, PointerError, encodeToken, formatPointer, parsePointer, resolve } from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

/**
 * Whether a value is a plain data object (not an array, not a class instance).
 *
 * @param {unknown} value candidate value
 * @returns {boolean} true when it is a plain object
 */
function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/**
 * Whether a value can be represented as JSON data.
 *
 * @param {unknown} value candidate value
 * @returns {boolean} true when it is valid JSON data
 */
function isJSONValue(value) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'string' || type === 'boolean') return true;
  if (type === 'number') return Number.isFinite(value);
  if (Array.isArray(value)) return value.every(isJSONValue);
  if (isPlainObject(value)) return Object.keys(value).every((key) => isJSONValue(value[key]));
  return false;
}

/**
 * Set a plain own property, bypassing any inherited accessor (e.g. `__proto__`).
 *
 * @param {object} obj target object
 * @param {string} key property name
 * @param {unknown} value property value
 */
function setProperty(obj, key, value) {
  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
}

/**
 * Deep-copy JSON data, treating every key (including `__proto__`) as an ordinary own property.
 *
 * @param {unknown} value JSON data to copy
 * @returns {unknown} an independent copy
 */
function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) setProperty(result, key, cloneValue(value[key]));
    return result;
  }
  return value;
}

/**
 * Compare two JSON values structurally: object members in any order, array elements in order.
 *
 * @param {unknown} a left value
 * @param {unknown} b right value
 * @returns {boolean} true when they are structurally equal
 */
function jsonEquals(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, i) => jsonEquals(item, b[i]));
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    return (
      aKeys.length === bKeys.length &&
      aKeys.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEquals(a[key], b[key]))
    );
  }
  return false;
}

/**
 * Insert a value at a pointer, creating or overwriting an object member or inserting into an array.
 *
 * @param {unknown} document document to mutate
 * @param {string} path target pointer
 * @param {unknown} value value to insert, already cloned
 * @returns {unknown} the resulting document
 */
function addAt(document, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const lastToken = tokens[tokens.length - 1];
  const parent = resolve(document, parentPointer);
  const fullPath = `${parentPointer}/${encodeToken(lastToken)}`;
  if (Array.isArray(parent)) {
    let index;
    if (lastToken === '-') {
      index = parent.length;
    } else {
      if (!ARRAY_INDEX.test(lastToken)) throw new PointerError(`invalid array index: ${lastToken} at ${fullPath}`, path);
      index = Number(lastToken);
      if (index > parent.length) throw new PointerError(`index out of range: ${lastToken} at ${fullPath}`, path);
    }
    parent.splice(index, 0, value);
  } else if (parent !== null && typeof parent === 'object') {
    setProperty(parent, lastToken, value);
  } else {
    const type = parent === null ? 'null' : typeof parent;
    throw new PointerError(`cannot index into ${type} at ${fullPath}`, path);
  }
  return document;
}

/**
 * Replace the value at a pointer, requiring that it already exists.
 *
 * @param {unknown} document document to mutate
 * @param {string} path target pointer
 * @param {unknown} value replacement value, already cloned
 * @returns {unknown} the resulting document
 */
function replaceAt(document, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  resolve(document, path);
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const lastToken = tokens[tokens.length - 1];
  const parent = resolve(document, parentPointer);
  if (Array.isArray(parent)) {
    parent[Number(lastToken)] = value;
  } else {
    setProperty(parent, lastToken, value);
  }
  return document;
}

/**
 * Remove the value at a pointer, requiring that it already exists.
 *
 * @param {unknown} document document to mutate
 * @param {string} path target pointer
 * @returns {unknown} the removed value
 */
function removeAt(document, path) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) throw new Error('cannot remove the whole document');
  const value = resolve(document, path);
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const lastToken = tokens[tokens.length - 1];
  const parent = resolve(document, parentPointer);
  if (Array.isArray(parent)) {
    parent.splice(Number(lastToken), 1);
  } else {
    delete parent[lastToken];
  }
  return value;
}

/**
 * Move a value from one pointer to another.
 *
 * @param {unknown} document document to mutate
 * @param {string} from source pointer
 * @param {string} path destination pointer
 * @returns {unknown} the resulting document
 */
function moveOperation(document, from, path) {
  const fromTokens = parsePointer(from);
  const pathTokens = parsePointer(path);
  const isProperPrefix = fromTokens.length < pathTokens.length && fromTokens.every((token, i) => token === pathTokens[i]);
  if (isProperPrefix) throw new Error('cannot move a value into its own child');
  if (from === path) {
    resolve(document, from);
    return document;
  }
  const value = removeAt(document, from);
  return addAt(document, path, value);
}

/**
 * Validate and execute a single patch operation.
 *
 * @param {unknown} document document to mutate
 * @param {unknown} operation the operation to apply
 * @returns {unknown} the resulting document
 */
function applyOperation(document, operation) {
  if (typeof operation !== 'object' || operation === null || Array.isArray(operation)) {
    throw new Error('operation must be an object');
  }
  const op = operation.op;
  const validOps = ['add', 'remove', 'replace', 'move', 'copy', 'test'];
  if (!validOps.includes(op)) throw new Error(`unknown operation: ${op}`);

  if (!('path' in operation) || operation.path === undefined) throw new Error(`${op} requires a path`);
  const path = operation.path;

  if (op === 'move' || op === 'copy') {
    if (!('from' in operation) || operation.from === undefined) throw new Error(`${op} requires a from`);
  }
  if (op === 'add' || op === 'replace' || op === 'test') {
    if (!('value' in operation)) throw new Error(`${op} requires a value`);
  }

  switch (op) {
    case 'add': {
      if (!isJSONValue(operation.value)) throw new Error('value is not JSON data');
      return addAt(document, path, cloneValue(operation.value));
    }
    case 'replace': {
      if (!isJSONValue(operation.value)) throw new Error('value is not JSON data');
      return replaceAt(document, path, cloneValue(operation.value));
    }
    case 'remove': {
      removeAt(document, path);
      return document;
    }
    case 'move': {
      return moveOperation(document, operation.from, path);
    }
    case 'copy': {
      const value = cloneValue(resolve(document, operation.from));
      return addAt(document, path, value);
    }
    case 'test': {
      const value = resolve(document, path);
      if (!isJSONValue(operation.value)) throw new Error('value is not JSON data');
      if (!jsonEquals(value, operation.value)) throw new Error(`test failed at ${path}`);
      return document;
    }
    default:
      throw new Error(`unknown operation: ${op}`);
  }
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!isJSONValue(document)) throw new TypeError('document is not JSON data');
  if (!Array.isArray(operations)) throw new TypeError('patch must be an array');

  let working = cloneValue(document);

  operations.forEach((operation, index) => {
    try {
      working = applyOperation(working, operation);
    } catch (error) {
      if (error instanceof PointerError) throw new PatchError(error.message, index, { cause: error });
      throw new PatchError(error.message, index);
    }
  });

  return working;
}
"}

