 * Prefix index over Unicode strings.
 *
 * Each node represents a distinct prefix of some stored word, keyed by
 * single Unicode code points (never surrogate halves). Every node keeps a
 * count of how many stored words live in its subtree, so prefix counts are
 * O(prefix length) instead of a subtree walk.
 */

/**
 * A single trie node.
 */
class TrieNode {
  /** @type {Map<string, TrieNode>} */
  children = new Map();

  /** @type {boolean} True when a word ends exactly at this node. */
  hasValue = false;

  /** @type {unknown} Value stored for the word ending here, if any. */
  value = undefined;

  /** @type {number} Number of stored words in this node's subtree (this node included). */
  count = 0;
}

/**
 * Splits a string into an array of single Unicode code points.
 * @param {string} text Text to split.
 * @returns {string[]} Array of code point strings.
 */
function toCodePoints(text) {
  return Array.from(text);
}

/**
 * Compares two single code point strings by code point value.
 * @param {string} a First code point.
 * @param {string} b Second code point.
 * @returns {number} Negative, zero, or positive.
 */
function compareCodePoints(a, b) {
  return a.codePointAt(0) - b.codePointAt(0);
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #size = 0;

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');

    const codePoints = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const cp of codePoints) {
      let child = node.children.get(cp);
      if (!child) {
        child = new TrieNode();
        node.children.set(cp, child);
        this.#nodeCount += 1;
      }
      path.push(child);
      node = child;
    }

    const isNew = !node.hasValue;
    const previous = node.value;
    node.hasValue = true;
    node.value = value;

    if (isNew) {
      for (const n of path) n.count += 1;
      this.#size += 1;
      return undefined;
    }
    return previous;
  }

  /**
   * Finds the node exactly matching a word, if any.
   * @param {string} word Word to find.
   * @returns {TrieNode | undefined} Node for the word, or undefined.
   */
  #findNode(word) {
    let node = this.#root;
    for (const cp of toCodePoints(word)) {
      const child = node.children.get(cp);
      if (!child) return undefined;
      node = child;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return node && node.hasValue ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return !!(node && node.hasValue);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');

    const codePoints = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const cp of codePoints) {
      const child = node.children.get(cp);
      if (!child) return false;
      path.push(child);
      node = child;
    }

    if (!node.hasValue) return false;

    node.hasValue = false;
    node.value = undefined;
    for (const n of path) n.count -= 1;
    this.#size -= 1;

    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count > 0 || current.hasValue || current.children.size > 0) break;
      const parent = path[i - 1];
      parent.children.delete(codePoints[i - 1]);
      this.#nodeCount -= 1;
    }

    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    const node = this.#findNode(prefix);
    return node ? node.count : 0;
  }

  /**
   * Recursively collects [word, value] pairs from a node in code point order.
   * @param {TrieNode} node Node to collect from.
   * @param {string} prefix Accumulated prefix text.
   * @param {Array<[string, unknown]>} results Output accumulator.
   * @param {number} limit Maximum number of results to collect.
   * @returns {boolean} True once the limit has been reached.
   */
  #collect(node, prefix, results, limit) {
    if (node.hasValue) {
      results.push([prefix, node.value]);
      if (results.length >= limit) return true;
    }
    const keys = Array.from(node.children.keys()).sort(compareCodePoints);
    for (const cp of keys) {
      if (this.#collect(node.children.get(cp), prefix + cp, results, limit)) return true;
    }
    return false;
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    if (limit !== Number.POSITIVE_INFINITY && !(Number.isSafeInteger(limit) && limit >= 0)) {
      throw new TypeError('limit must be a non-negative integer');
    }
    if (limit === 0) return [];

    const node = this.#findNode(prefix);
    if (!node) return [];

    const results = [];
    this.#collect(node, prefix, results, limit);
    return results.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const results = [];
    this.#collect(this.#root, '', results, Number.POSITIVE_INFINITY);
    return results;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    if (typeof text !== 'string') throw new TypeError('text must be a string');

    let node = this.#root;
    let best = node.hasValue ? { word: '', value: node.value } : null;
    let current = '';

    for (const cp of toCodePoints(text)) {
      const child = node.children.get(cp);
      if (!child) break;
      current += cp;
      node = child;
      if (node.hasValue) best = { word: current, value: node.value };
    }

    return best;
  }
}
