import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function endOfInput() {
    return new ExprError(`unexpected end of input at ${input.length}`, input.length);
  }

  function unexpectedToken(token) {
    return new ExprError(`unexpected token '${String(token.value)}' at ${token.index}`, token.index);
  }

  function parseAtom() {
    const token = tokens[pos];
    if (!token) throw endOfInput();
    if (token.type === 'number') {
      pos += 1;
      return { type: 'number', value: token.value, index: token.index };
    }
    if (token.type === 'name') {
      pos += 1;
      if (tokens[pos] && tokens[pos].type === 'lparen') {
        pos += 1;
        const args = [];
        if (!(tokens[pos] && tokens[pos].type === 'rparen')) {
          args.push(parseAddSub());
          while (tokens[pos] && tokens[pos].type === 'comma') {
            pos += 1;
            args.push(parseAddSub());
          }
        }
        if (tokens[pos] && tokens[pos].type === 'rparen') {
          pos += 1;
        } else if (!tokens[pos]) {
          throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
        } else {
          throw unexpectedToken(tokens[pos]);
        }
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }
    if (token.type === 'lparen') {
      pos += 1;
      const expr = parseAddSub();
      if (tokens[pos] && tokens[pos].type === 'rparen') {
        pos += 1;
      } else if (!tokens[pos]) {
        throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
      } else {
        throw new ExprError(`missing closing parenthesis at ${tokens[pos].index}`, tokens[pos].index);
      }
      return expr;
    }
    throw unexpectedToken(token);
  }

  function parseExponent() {
    let base = parseAtom();
    if (tokens[pos] && tokens[pos].type === 'operator' && tokens[pos].value === '^') {
      const opToken = tokens[pos];
      pos += 1;
      const right = parseUnary();
      base = { type: 'binary', op: '^', left: base, right, index: opToken.index };
    }
    return base;
  }

  function parseUnary() {
    const token = tokens[pos];
    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      pos += 1;
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parseExponent();
  }

  function parseMulDiv() {
    let left = parseUnary();
    while (
      tokens[pos] &&
      tokens[pos].type === 'operator' &&
      (tokens[pos].value === '*' || tokens[pos].value === '/' || tokens[pos].value === '%')
    ) {
      const opToken = tokens[pos];
      pos += 1;
      const right = parseUnary();
      left = { type: 'binary', op: opToken.value, left, right, index: opToken.index };
    }
    return left;
  }

  function parseAddSub() {
    let left = parseMulDiv();
    while (
      tokens[pos] &&
      tokens[pos].type === 'operator' &&
      (tokens[pos].value === '+' || tokens[pos].value === '-')
    ) {
      const opToken = tokens[pos];
      pos += 1;
      const right = parseMulDiv();
      left = { type: 'binary', op: opToken.value, left, right, index: opToken.index };
    }
    return left;
  }

  const tree = parseAddSub();
  if (pos < tokens.length) {
    throw unexpectedToken(tokens[pos]);
  }
  return tree;
}
